      headSha: resolveHeadSha(repoRoot),
      policyMode: resolveStudioPolicyMode(repoRoot),
      lastCheckpoints,
      refreshedAtMs: Date.now(),
      value: result,
    };
    return result;
  })();
  inFlightByKey.set(inFlightKey, pending);
  try {
    return await pending;
