export async function replaceReviewFindings(
  db: D1Database,
  reviewId: string,
  findings: ReviewFinding[],
  options?: { startNumber?: number }
): Promise<void> {
  await db.prepare('DELETE FROM review_findings WHERE review_id = ?').bind(reviewId).run();

